head.script:
scwin.screenId = "jldstf50000";

///////// 1. 변수 및 선언 영역 /////////

scwin.gUsrId = undefined;

scwin.vScrenID = 'ULDSTF50000.gfm';

scwin.gPwChkResult = undefined;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.dts_usr_basic.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=USER_INOUT";
        scwin.dts_usr_basic.reset();
        scwin.dts_dscl_noti.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=NOTI_INOUT";
        scwin.dts_dscl_noti.reset();
        scwin.dts_basic.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=USER_INOUT";
        scwin.dts_basic.reset();
        scwin.getSessionData();
        await scwin.readBasicInfo();
        $c.fil.showObj(ipt_txb_Pw, false);
        $c.fil.showObj(ipt_txb_EncPw, false);
        $c.fil.showObj(ipt_txb_EncPrePw, false);
        $c.fil.showObj(ipt_txb_EncNewPw, false);
        $c.util.getComponent('tab_UsrInfo').setSelectedIndex(1);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf50000.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts_usr_basic = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsUsrBasic')) : $c.util.getComponent('dtsUsrBasic');

scwin.dts_dscl_noti = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsDsclNoti')) : $c.util.getComponent('dtsDsclNoti');

scwin.dts_pwCheck = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsPwCheck')) : $c.util.getComponent('dtsPwCheck');

scwin.dts_pwHashEnc = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsPwHashEnc')) : $c.util.getComponent('dtsPwHashEnc');

scwin.dts_basic = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsBasic')) : $c.util.getComponent('dtsBasic');

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf50000.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

