/**
 * @method
 * @name scwin.trs_basic_modify_onsuccess
 * @author Inswave
 * @date 2026. 09. 29
 * @description txb_Msg 을(를) 값을 넣는다 외
 * @param
 * @returns
 * @hidden N
*/
scwin.trs_basic_modify_onsuccess = async function () {
    /* sdd-asis-lifecycle:begin trs_basic_modify_onsuccess — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("ipt_txb_Msg").setValue($c.data.getMessage("MSG-0001", ""));
    const index = tab_UsrInfo.selectedIndex;
    if (index == 1) {
        await scwin.readBasicInfo();
    } else {
        await scwin.readDsclNoti();
    }
    /* sdd-asis-lifecycle:end */
};

