/**
 * @event
 * @name scwin.tab_UsrInfo_onselchanged
 * @author Inswave
 * @date 2026. 09. 29
 * @param nIndex
 * @returns
 * @hidden N
*/
scwin.tab_UsrInfo_onselchanged = async function (nIndex) {
    try {
        /* sdd-asis-lifecycle:begin tab_UsrInfo_onselchanged — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if (nIndex == 1) {
            await scwin.readBasicInfo();
            $c.util.getComponent("ipt_txb_Msg").setValue("");
        } else {
            if (nIndex == 2) {
                await scwin.readDsclNoti();
                $c.util.getComponent("ipt_txb_Msg").setValue("");
            }
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf50000.tab_UsrInfo_onselchanged' }); }
};

