/**
 * @method
 * @name scwin.dts_pwCheck_onloadcompleted
 * @author Inswave
 * @date 2026. 09. 29
 * @description 알림을 띄운다 외
 * @param rowcount
 * @returns
 * @hidden N
*/
scwin.dts_pwCheck_onloadcompleted = async function (rowcount) {
    /* sdd-asis-lifecycle:begin dts_pwCheck_onloadcompleted — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let result = scwin.dts_pwCheck.getCellData(1, "RESULT_STR");
    result = $c.str.replaceAll(result, '<br>', '\n');
    result = $c.str.replaceAll(result, '&nbsp;', ' ');
    await $c.win.alert(result);
    if (result.indexOf("사용가능여부 : O") >= 0) {
        (scwin.dts_basic.insertRow(), scwin.dts_basic.setRowPosition(scwin.dts_basic.getRowCount()-1));
        scwin.dts_basic.setCellData(1, "USR_ID", ipt_txb_UsrId.value);
        if (ipt_txb_TelNo1.value !== '') {
            scwin.dts_basic.setCellData(1, "TEL_NO", ipt_txb_TelNo1.value + '-' + ipt_txb_TelNo2.value + '-' + ipt_txb_TelNo3.value);
        } else {
            scwin.dts_basic.setCellData(1, "TEL_NO", '');
        }
        scwin.dts_basic.setCellData(1, "TEL_NO1", ipt_txb_TelNo1.value);
        scwin.dts_basic.setCellData(1, "TEL_NO2", ipt_txb_TelNo2.value);
        scwin.dts_basic.setCellData(1, "TEL_NO3", ipt_txb_TelNo3.value);
        scwin.dts_basic.setCellData(1, "TEL_INNR_NO", ipt_txb_TelInnrNo.value);
        scwin.dts_basic.setCellData(1, "FAX_NO", ipt_txb_FaxNo.value);
        scwin.dts_basic.setCellData(1, "EMAIL", ipt_txb_Email.value);
        scwin.dts_basic.setCellData(1, "NEW_PW", ipt_txb_EncNewPw.value);
        const vAnswer = await $c.win.confirm($c.data.getMessage("MSG-0004", ""));
        if (vAnswer === true) {
            if (await scwin.isOkTelNo()) {
                trs_basic_modify.Action = "/Mypage.do?method=modifyUserInfo&inputMessageId=USER_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + $c.fil.SCREN_PROCS_TP_CD_02;
                trs_basic_modify.KeyName = "toinb_dataid4";
                trs_basic_modify.KeyValue = "JSP(I:pInput=dts_basic)";
                trs_basic_modify.Post();
            }
        }
    } else {

    }
    /* sdd-asis-lifecycle:end */
};

