/**
 * @method
 * @name scwin.tx_script_dts_usr_basic
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_script_dts_usr_basic = async function () {
    $c.util.getComponent("dma_scriptDtsUsrBasicReq").set("inputMessageId", "USER_INOUT");
    $c.util.getComponent("dma_scriptDtsUsrBasicReq").set("outputMessageId", "USER_INOUT");
    $c.util.getComponent("dma_scriptDtsUsrBasicReq").set("SCREN_ID", 'ULDSTF50000.gfm');
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD", unresolved: "query_param:SCREN_PROCES_TP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_usr_basic",
        method: "post",
        action: "/Mypage.do",
        ref: "dma_scriptDtsUsrBasicReq",
        target: "dtsUsrBasic=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_usr_basic_onloaderror'] === 'function') ? scwin['dts_usr_basic_onloaderror'] : (typeof scwin['dts_usr_basic_onfail'] === 'function') ? scwin['dts_usr_basic_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_usr_basic_onloadcompleted'] === 'function') ? scwin['dts_usr_basic_onloadcompleted'] : ((typeof scwin['dts_usr_basic_onsuccess'] === 'function') ? scwin['dts_usr_basic_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dtsUsrBasic'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf50000.tx_script_dts_usr_basic" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

