/**
 * @method
 * @name scwin.modifyDsclNoti
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.modifyDsclNoti = async function () {
    /* sdd-asis-lifecycle:begin fn_ModifyDsclNoti — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let vCntAll = 0;
    if (chk_chb_NotiKind03.checked === true) {
        scwin.dts_dscl_noti.setCellData(1, "S3", chk_chb_NotiKind03.value);
        vCntAll++;
    } else {
        scwin.dts_dscl_noti.setCellData(1, "S3", "");
    }
    if (chk_chb_NotiKind04.checked === true) {
        scwin.dts_dscl_noti.setCellData(1, "S4", chk_chb_NotiKind04.value);
        vCntAll++;
    } else {
        scwin.dts_dscl_noti.setCellData(1, "S4", "");
    }
    if (chk_chb_NotiKind05.checked === true) {
        scwin.dts_dscl_noti.setCellData(1, "S5", chk_chb_NotiKind05.value);
        vCntAll++;
    } else {
        scwin.dts_dscl_noti.setCellData(1, "S5", "");
    }
    if (vCntAll > 0) {
        scwin.dts_dscl_noti.setCellData(1, "CELLPHONE_NOTI_YN", "Y");
    } else {
        scwin.dts_dscl_noti.setCellData(1, "CELLPHONE_NOTI_YN", "N");
    }
    const vAnswer = await $c.win.confirm($c.data.getMessage("MSG-0004", ""));
    if (vAnswer === true) {
        const url = "/Mypage.do?method=modifyDsclNoti&inputMessageId=NOTI_INOUT";
        "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + $c.fil.SCREN_PROCS_TP_CD_02;
        trs_basic_modify.Action = "/Mypage.do?method=modifyDsclNoti&inputMessageId=NOTI_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + $c.fil.SCREN_PROCS_TP_CD_02;
        trs_basic_modify.KeyName = "toinb_dataid4";
        trs_basic_modify.KeyValue = "JSP(I:pInput=dts_dscl_noti)";
        trs_basic_modify.Post();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isOkTelNo
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.isOkTelNo = async function () {
    /* sdd-asis-lifecycle:begin isOkTelNo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let isOk = false;
    const TEL_1 = ipt_txb_TelNo1.value;
    const TEL_2 = ipt_txb_TelNo2.value;
    const TEL_3 = ipt_txb_TelNo3.value;
    const TEL_INNR = ipt_txb_TelInnrNo.value;
    if (spaceCheck(ipt_txb_TelNo1) && spaceCheck(ipt_txb_TelNo2) && spaceCheck(ipt_txb_TelNo3) && spaceCheck(ipt_txb_TelInnrNo)) {
        if (TEL_1 === '' && TEL_2 === '' && TEL_3 === '' && TEL_INNR === '') {
            isOk = true;
        } else {
            if (TEL_1 !== '' && TEL_2 !== '' && TEL_3 !== '') {
                if (isOnlyNumber(ipt_txb_TelNo1) && isOnlyNumber(ipt_txb_TelNo2) && isOnlyNumber(ipt_txb_TelNo3)) {
                    if (TEL_INNR === '') {
                        isOk = true;
                    } else {
                        if (isOnlyNumber(ipt_txb_TelInnrNo)) {
                            isOk = true;
                        } else {
                            isOk = false;
                        }
                    }
                } else {
                    isOk = false;
                }
            } else {
                await $c.win.alert('전화번호 : [국번][앞번호][뒷번호]는 필수 입니다.');
                isOk = false;
            }
        }
    } else {
        isOk = false;
    }
    return isOk;
    /* sdd-asis-lifecycle:end */
};


/**
