scwin.encPw = function () {
    /* sdd-asis-lifecycle:begin fn_EncPw — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (scwin.dts_basic.insertRow(), scwin.dts_basic.setRowPosition(scwin.dts_basic.getRowCount()-1));
    const aesPrePw = fn_AES256(ipt_txb_PrePw.value);
    $c.fil.setObjectValue(ipt_txb_EncPrePw, aesPrePw);
    scwin.dts_basic.setCellData(1, "PRE_PW", ipt_txb_EncPrePw.value);
    trs_pass_enc.Action = "/ListedCompanyPassword.do?method=getPwHashEncryptStringPost";
    trs_pass_enc.KeyName = "toinb_dataid4";
    trs_pass_enc.KeyValue = "JSP(O:pOutput=dts_pwHashEnc,I:pInput=dts_basic)";
    trs_pass_enc.Post();
    /* sdd-asis-lifecycle:end */
};


